// backend/src/functions/SyntheticDataFunction/index.ts
const BATCH_SIZE = 5; // 동시 처리 개수

async function generatePartsInBatches(count: number) {
  const parts = [];
  for (let i = 0; i < count; i += BATCH_SIZE) {
    const batch = Array.from({ length: Math.min(BATCH_SIZE, count - i) })
      .map((_, idx) => generateSinglePart(i + idx));

    const results = await Promise.all(batch);
    parts.push(...results);
  }
  return parts;
}
```

